// Map n8n Gmail Trigger output (Simplify on OR raw API) → Denizen inbound shape.
const item = $input.item.json || {};

function header(name) {
  for (const headers of [item.payload?.headers, item.headers].filter(Array.isArray)) {
    const hit = headers.find((h) => String(h.name || '').toLowerCase() === name.toLowerCase());
    if (hit) return String(hit.value || '');
  }
  return '';
}

function fromAddress() {
  const direct = item.from || item.From;
  if (typeof direct === 'string' && direct.trim()) return direct.trim();
  if (direct && typeof direct === 'object') {
    const v = direct.value?.[0] || direct;
    const addr = v.address || v.email || '';
    const name = v.name || '';
    if (name && addr) return `${name} <${addr}>`;
    return String(addr || name || '').trim();
  }
  return header('from').trim();
}

function extractBody(part) {
  if (!part) return '';
  if (part.mimeType === 'text/plain' && part.body?.data) {
    return Buffer.from(part.body.data, 'base64').toString('utf8');
  }
  if (Array.isArray(part.parts)) {
    for (const p of part.parts) {
      const t = extractBody(p);
      if (t) return t;
    }
  }
  return '';
}

const from = fromAddress();
const subject = String(item.subject || item.Subject || header('subject') || '').trim();
let body = String(item.textPlain || item.text || item.body || item.snippet || '').trim();
if (!body) body = extractBody(item.payload).trim();

return [{
  json: {
    from,
    subject,
    body,
    threadId: item.threadId || item.thread_id || null,
    messageId: item.id || item.messageId || null,
  },
}];
